package main

import (
	"context"
	"errors"
	"fmt"
	"net/http"
)

// 1. 自定义错误类型，实现 Unwrap 参与 errors.Is/As 链
type BizError struct {
	Code  string
	HTTP  int
	Retry bool
	Cause error
}

func (e *BizError) Error() string { return fmt.Sprintf("%s: %v", e.Code, e.Cause) }
func (e *BizError) Unwrap() error { return e.Cause }

var ErrUserNotFound = errors.New("user not found") // sentinel

func loadUser(ctx context.Context, id int) error {
	// 模拟底层超时
	if err := ctx.Err(); err != nil {
		return fmt.Errorf("loadUser id=%d: %w", id, err) // %w 保留 context.DeadlineExceeded
	}
	return fmt.Errorf("loadUser id=%d: %w", id, ErrUserNotFound)
}

func getUser(ctx context.Context, id int) error {
	if err := loadUser(ctx, id); err != nil {
		// Service 层包成 BizError，注意返回类型是 error（接口），避免 typed nil
		return &BizError{Code: "USER_NOT_FOUND", HTTP: 404, Retry: false, Cause: err}
	}
	return nil
}

// 2. typed nil 反例：返回具体指针类型时，nil 指针被装入接口，err != nil 永远成立
func badReturn() error {
	var e *BizError // nil
	return e // 调用方 if err != nil 为 true！
}

// 3. defer + recover 转 error，常用于 HTTP 中间件兜底
func safeCall(fn func()) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("panic recovered: %v", r) // 生产里还应记录 debug.Stack()
		}
	}()
	fn()
	return nil
}

// 4. Handler 边界：errors.As 解结构化错误，errors.Is 解 sentinel
func handle(w http.ResponseWriter, r *http.Request) {
	err := getUser(r.Context(), 7)
	var be *BizError
	switch {
	case err == nil:
		w.WriteHeader(http.StatusOK)
	case errors.Is(err, context.DeadlineExceeded):
		http.Error(w, "upstream timeout", http.StatusGatewayTimeout) // 504
	case errors.As(err, &be):
		http.Error(w, be.Code, be.HTTP) // 用结构化字段映射
	default:
		http.Error(w, "internal", http.StatusInternalServerError) // 兜底，记录 stack
	}
}
